// RECONCILIATION — the gate every derived figure has to pass through.
//
// Every other capability here is arithmetic over a list of transactions, and arithmetic over an
// INCOMPLETE list is not wrong in a way anybody can see. A missing week of a statement does not
// produce an error; it produces a spending total that is quietly too low, a runway that is quietly
// too long, and a payoff schedule that quietly does not work. The numbers stay plausible, which is
// exactly what makes them dangerous.
//
// So reconciliation is not a report — it is a TYPE. `reconcile` is the only function that can mint a
// `ReconciledLedger`, and a capability that takes one cannot be handed transactions nobody checked.
// The compiler enforces the precedence, rather than a comment asking politely.
//
// THERE IS NO TOLERANCE, and that is deliberate. Money here is an integer count of minor units, so a
// one-cent discrepancy has no rounding to blame — it is a real transaction that is missing, doubled,
// or signed the wrong way. A tolerance would be a setting whose only function is to hide the class of
// defect this module exists to find.
import { type Money, money, sum, subtract, isZero } from "@/features/finance/lib/money";
import { type Txn, daysBetween } from "@/features/finance/lib/txn";

/** One statement: what the institution says the account held at each end of a window. */
export interface StatementPeriod {
  readonly account: string;
  /** `YYYY-MM-DD`, INCLUSIVE. */
  readonly from: string;
  /** `YYYY-MM-DD`, INCLUSIVE. */
  readonly to: string;
  readonly opening: Money;
  readonly closing: Money;
}

export type ProblemKind =
  /** Opening + the period's transactions does not reach closing. */
  | "unbalanced"
  /** Consecutive statements leave days uncovered — transactions in them are simply absent. */
  | "gap"
  /** Two statements for one account claim the same days. */
  | "overlap"
  /** One statement's opening disagrees with the previous statement's closing. */
  | "continuity"
  /** A transaction's currency is not the period's. */
  | "currency";

export interface Problem {
  readonly kind: ProblemKind;
  readonly account: string;
  /** Written for a person to act on, not for a log. */
  readonly detail: string;
  /** The size of the disagreement, where the problem has one. */
  readonly amount?: Money;
  /** Transactions this problem points at — the shortlist to go and look at. */
  readonly suspects?: readonly Txn[];
}

export interface PeriodReport {
  readonly account: string;
  readonly from: string;
  readonly to: string;
  readonly balanced: boolean;
  readonly opening: Money;
  readonly closing: Money;
  /** opening + everything dated inside the window. */
  readonly computed: Money;
  /** closing − computed. Zero, or the exact size of what is wrong. */
  readonly discrepancy: Money;
  readonly counted: number;
  readonly problems: readonly Problem[];
}

// The brand is COMPILE-TIME ONLY — `declare` means it never exists at runtime, so a ledger costs
// nothing to carry and `mint` below is the only thing that can assert it. A real symbol would
// have to be exported for the interface to be nameable outside this module, and exporting it is
// exactly what would let anything construct a ledger.
declare const RECONCILED: unique symbol;

/**
 * Transactions something has actually checked, and the date they are checked THROUGH.
 *
 * Only `reconcile` and the deliberately-named `unverifiedLedger` can produce one, so a capability
 * that asks for a `ReconciledLedger` cannot be handed a raw array by accident.
 */
export interface ReconciledLedger {
  readonly [RECONCILED]: true;
  readonly txns: readonly Txn[];
  /** The last date EVERY account is covered through — see `coverageThrough`. */
  readonly through: string;
  readonly accounts: readonly string[];
  /** True when this ledger came from `unverifiedLedger` rather than a passing reconcile. */
  readonly unverified: boolean;
  /** Why it was accepted unverified, when it was. */
  readonly caveat?: string;
}

export interface ReconcileResult {
  readonly ok: boolean;
  /** Present only when every period balanced and nothing is missing between them. */
  readonly ledger?: ReconciledLedger;
  readonly periods: readonly PeriodReport[];
  readonly problems: readonly Problem[];
  /** Transactions belonging to no supplied period. Not counted, and not silently dropped either. */
  readonly uncovered: readonly Txn[];
}

const nextDay = (d: string): string =>
  new Date(Date.parse(`${d}T00:00:00Z`) + 86_400_000).toISOString().slice(0, 10);

const inPeriod = (t: Txn, p: StatementPeriod): boolean =>
  t.account === p.account && t.date >= p.from && t.date <= p.to;

/**
 * The last date the WHOLE picture is trustworthy through — the EARLIEST of each account's coverage.
 *
 * A ledger is only as complete as its least-covered account. Checking reconciled through August and
 * a credit card only through July does not give you an August position: August's card spending is
 * missing, so every August figure is too flattering. Taking the maximum here would be the specific
 * mistake that produces a confident, wrong number.
 */
export function coverageThrough(periods: readonly StatementPeriod[]): string | undefined {
  if (!periods.length) return undefined;
  const last = new Map<string, string>();
  for (const p of periods) {
    const seen = last.get(p.account);
    if (!seen || p.to > seen) last.set(p.account, p.to);
  }
  return [...last.values()].sort()[0];
}

/** Explain a discrepancy by pointing at the transactions that would produce exactly it. */
function explain(discrepancy: number, rows: readonly Txn[]): { detail: string; suspects: Txn[] } {
  // A SIGN ERROR IS TWICE THE AMOUNT, and it is checked FIRST. Booking −$50 as +$50 moves the
  // balance by $100, so a $100 discrepancy with a $50 transaction present is far more likely a sign
  // error than a missing $100 charge — and the two want completely different fixes.
  const halved = rows.filter((t) => Math.abs(t.amount.minor) * 2 === Math.abs(discrepancy));
  if (halved.length) {
    return {
      detail: `the discrepancy is exactly twice ${halved.length === 1 ? "one transaction" : `${halved.length} transactions`} — a sign error, not a missing row: money leaving the account must be negative`,
      suspects: halved,
    };
  }
  const exact = rows.filter((t) => Math.abs(t.amount.minor) === Math.abs(discrepancy));
  if (exact.length) {
    return {
      detail: `the discrepancy is exactly ${exact.length === 1 ? "one transaction" : `${exact.length} transactions`} in this period — check whether it was counted twice, or a matching one is missing`,
      suspects: exact,
    };
  }
  return { detail: "no single transaction accounts for it — the statement is probably missing rows", suspects: [] };
}

/** The ONLY place the brand is asserted. Private on purpose: it is the whole enforcement. */
const mint = (l: Omit<ReconciledLedger, typeof RECONCILED>): ReconciledLedger => l as ReconciledLedger;

export function reconcile(
  txns: readonly Txn[],
  periods: readonly StatementPeriod[],
): ReconcileResult {
  const problems: Problem[] = [];
  const reports: PeriodReport[] = [];
  const claimed = new Set<Txn>();

  for (const p of periods) {
    const rows = txns.filter((t) => inPeriod(t, p));
    for (const t of rows) claimed.add(t);

    const wrongCurrency = rows.filter((t) => t.amount.currency !== p.opening.currency);
    for (const t of wrongCurrency) {
      problems.push({
        kind: "currency",
        account: p.account,
        detail: `a ${t.amount.currency} transaction on ${t.date} sits in a ${p.opening.currency} statement — converting it is a decision, not an assumption this can make`,
        suspects: [t],
      });
    }

    const movement = sum(
      rows.filter((t) => t.amount.currency === p.opening.currency).map((t) => t.amount),
      p.opening.currency,
    );
    const computed = money(p.opening.minor + movement.minor, p.opening.currency);
    const discrepancy = subtract(p.closing, computed);
    const balanced = isZero(discrepancy) && wrongCurrency.length === 0;

    const own: Problem[] = [];
    if (!isZero(discrepancy)) {
      const { detail, suspects } = explain(discrepancy.minor, rows);
      own.push({
        kind: "unbalanced",
        account: p.account,
        detail: `${p.from}..${p.to} is out by ${discrepancy.minor} minor units — ${detail}`,
        amount: discrepancy,
        suspects,
      });
    }
    problems.push(...own);

    reports.push({
      account: p.account,
      from: p.from,
      to: p.to,
      balanced,
      opening: p.opening,
      closing: p.closing,
      computed,
      discrepancy,
      counted: rows.length,
      problems: [...own, ...wrongCurrency.map((t): Problem => ({
        kind: "currency",
        account: p.account,
        detail: `${t.amount.currency} transaction on ${t.date}`,
        suspects: [t],
      }))],
    });
  }

  // BETWEEN the statements, per account: a gap, an overlap, or an opening that disagrees with the
  // previous closing. Each period can balance perfectly and the SET still be missing a month.
  const byAccount = new Map<string, StatementPeriod[]>();
  for (const p of periods) {
    const bucket = byAccount.get(p.account);
    if (bucket) bucket.push(p);
    else byAccount.set(p.account, [p]);
  }
  for (const [account, ps] of byAccount) {
    const sorted = [...ps].sort((a, b) => a.from.localeCompare(b.from));
    for (let i = 1; i < sorted.length; i++) {
      const prev = sorted[i - 1];
      const next = sorted[i];
      if (next.from <= prev.to) {
        problems.push({
          kind: "overlap",
          account,
          detail: `${next.from}..${next.to} overlaps ${prev.from}..${prev.to} — the shared days would be counted twice`,
        });
        continue;
      }
      const missing = daysBetween(prev.to, next.from) - 1;
      if (missing > 0) {
        problems.push({
          kind: "gap",
          account,
          detail: `${missing} day(s) uncovered between ${prev.to} and ${next.from} — anything spent in them is absent, and every total below is too low by however much that was`,
        });
        continue;
      }
      if (next.opening.minor !== prev.closing.minor) {
        problems.push({
          kind: "continuity",
          account,
          detail: `${nextDay(prev.to)} opens at ${next.opening.minor} but ${prev.to} closed at ${prev.closing.minor} — consecutive statements disagree about the same moment`,
          amount: subtract(next.opening, prev.closing),
        });
      }
    }
  }

  const uncovered = txns.filter((t) => !claimed.has(t));
  const ok = problems.length === 0 && uncovered.length === 0 && periods.length > 0;
  const through = coverageThrough(periods);

  return {
    ok,
    ledger: ok && through
      ? mint({
          txns: [...txns].sort((a, b) => a.date.localeCompare(b.date)),
          through,
          accounts: [...byAccount.keys()].sort(),
          unverified: false,
        })
      : undefined,
    periods: reports,
    problems,
    uncovered,
  };
}

/**
 * A ledger accepted WITHOUT a reconcile, because sometimes there is no opening balance to check
 * against and a system that refuses outright is a system nobody uses.
 *
 * It is deliberately ugly to reach for: it demands a reason, it marks the ledger `unverified`, and
 * its name is greppable — so "which of these figures rests on unchecked data?" is a question with an
 * answer. A silent fallback inside `reconcile` would have removed that answer.
 */
export function unverifiedLedger(
  txns: readonly Txn[],
  through: string,
  caveat: string,
): ReconciledLedger {
  if (!caveat.trim()) throw new Error("an unverified ledger must say why it could not be reconciled");
  const sorted = [...txns].sort((a, b) => a.date.localeCompare(b.date));
  return mint({
    txns: sorted,
    through,
    accounts: [...new Set(sorted.map((t) => t.account))].sort(),
    unverified: true,
    caveat,
  });
}

/** The transactions a derived figure may use: everything up to the date coverage actually reaches. */
export const covered = (l: ReconciledLedger): readonly Txn[] => l.txns.filter((t) => t.date <= l.through);

/** A one-line statement of what a figure derived from this ledger is standing on. */
export function provenance(l: ReconciledLedger): string {
  const base = `${l.txns.length} transaction(s) across ${l.accounts.length} account(s), covered through ${l.through}`;
  return l.unverified ? `UNVERIFIED — ${l.caveat} · ${base}` : `reconciled · ${base}`;
}

