import { describe, it, expect } from "vitest";
import { fromMajor, type Money } from "@/features/finance/lib/money";
import type { Txn } from "@/features/finance/lib/txn";
import {
  type ReconciledLedger,
  type StatementPeriod,
  coverageThrough,
  covered,
  provenance,
  reconcile,
  unverifiedLedger,
} from "@/features/finance/lib/reconcile";

// SYNTHETIC FIXTURES ONLY. No real statement, balance or account number belongs in this repo.
const usd = (major: number): Money => fromMajor(major, "USD");
const tx = (date: string, description: string, major: number, account = "checking"): Txn => ({
  date,
  description,
  amount: usd(major),
  account,
});

const period = (over: Partial<StatementPeriod> = {}): StatementPeriod => ({
  account: "checking",
  from: "2026-06-01",
  to: "2026-06-30",
  opening: usd(1000),
  closing: usd(1000),
  ...over,
});

describe("reconcile — a period that balances", () => {
  const rows = [tx("2026-06-03", "ACME PAYROLL", 2000), tx("2026-06-05", "RENT", -1500)];

  it("balances and mints a ledger", () => {
    const r = reconcile(rows, [period({ closing: usd(1500) })]);
    expect(r.ok).toBe(true);
    expect(r.problems).toEqual([]);
    expect(r.periods[0].balanced).toBe(true);
    expect(r.periods[0].computed.minor).toBe(usd(1500).minor);
    expect(r.periods[0].discrepancy.minor).toBe(0);
    expect(r.ledger).toBeDefined();
    expect(r.ledger!.unverified).toBe(false);
    expect(r.ledger!.through).toBe("2026-06-30");
    expect(r.ledger!.accounts).toEqual(["checking"]);
  });

  it("mints NO ledger when anything is wrong — there is no partial pass", () => {
    const r = reconcile(rows, [period({ closing: usd(1501) })]);
    expect(r.ok).toBe(false);
    expect(r.ledger).toBeUndefined();
  });

  it("refuses a one-cent discrepancy — money is integers, so there is no rounding to blame", () => {
    const r = reconcile(rows, [period({ closing: usd(1500.01) })]);
    expect(r.ok).toBe(false);
    expect(r.periods[0].discrepancy.minor).toBe(1);
    expect(r.problems[0].kind).toBe("unbalanced");
  });
});

describe("reconcile — explaining a discrepancy", () => {
  it("calls a doubled amount a SIGN ERROR, not a missing row", () => {
    // RENT booked +1500 instead of −1500 moves the balance by 3000, not 1500. A detector that
    // matched the discrepancy against transaction amounts directly would go looking for a missing
    // $3,000 charge that does not exist, and the two want completely different fixes.
    const rows = [tx("2026-06-03", "ACME PAYROLL", 2000), tx("2026-06-05", "RENT", 1500)];
    const r = reconcile(rows, [period({ closing: usd(1500) })]);
    expect(r.ok).toBe(false);
    const p = r.problems.find((x) => x.kind === "unbalanced")!;
    expect(p.detail).toContain("sign error");
    expect(p.suspects!.map((t) => t.description)).toEqual(["RENT"]);
    expect(p.amount!.minor).toBe(usd(-3000).minor);
  });

  it("names the transaction whose amount is exactly the discrepancy", () => {
    const rows = [tx("2026-06-03", "ACME PAYROLL", 2000), tx("2026-06-05", "RENT", -1500)];
    // Closing is short by exactly the $2,000 payroll: it was probably counted twice somewhere.
    const r = reconcile(rows, [period({ closing: usd(3500) })]);
    const p = r.problems.find((x) => x.kind === "unbalanced")!;
    expect(p.detail).toContain("counted twice");
    expect(p.suspects!.map((t) => t.description)).toEqual(["ACME PAYROLL"]);
  });

  it("says so plainly when no single transaction explains it", () => {
    const rows = [tx("2026-06-03", "ACME PAYROLL", 2000)];
    const r = reconcile(rows, [period({ closing: usd(2777) })]);
    const p = r.problems.find((x) => x.kind === "unbalanced")!;
    expect(p.detail).toContain("missing rows");
    expect(p.suspects).toEqual([]);
  });
});

describe("reconcile — between the statements", () => {
  const june = period({ from: "2026-06-01", to: "2026-06-30", opening: usd(1000), closing: usd(1000) });

  it("finds days no statement covers, even when every statement balances", () => {
    // Both periods balance on their own. The SET is missing a week, and a spending total computed
    // from it is quietly too low by whatever happened in that week.
    const august = period({ from: "2026-08-01", to: "2026-08-31", opening: usd(1000), closing: usd(1000) });
    const r = reconcile([], [june, august]);
    expect(r.periods.every((p) => p.balanced)).toBe(true);
    expect(r.ok).toBe(false);
    const gap = r.problems.find((p) => p.kind === "gap")!;
    expect(gap.detail).toContain("31 day(s) uncovered");
  });

  it("finds two statements claiming the same days", () => {
    const overlapping = period({ from: "2026-06-15", to: "2026-07-15", opening: usd(1000), closing: usd(1000) });
    const r = reconcile([], [june, overlapping]);
    expect(r.problems.find((p) => p.kind === "overlap")).toBeDefined();
  });

  it("finds consecutive statements that disagree about the same moment", () => {
    const july = period({ from: "2026-07-01", to: "2026-07-31", opening: usd(900), closing: usd(900) });
    const r = reconcile([], [june, july]);
    const c = r.problems.find((p) => p.kind === "continuity")!;
    expect(c.detail).toContain("2026-07-01");
    expect(c.amount!.minor).toBe(usd(-100).minor);
  });

  it("accepts statements that abut exactly", () => {
    const july = period({ from: "2026-07-01", to: "2026-07-31", opening: usd(1000), closing: usd(1000) });
    const r = reconcile([], [june, july]);
    expect(r.problems).toEqual([]);
    expect(r.ok).toBe(true);
  });
});

describe("reconcile — coverage is the LEAST covered account", () => {
  it("takes the earliest account's end date, never the latest", () => {
    // Checking is reconciled through August and the card only through July. There is no August
    // position: August's card spending is missing, so every August figure would be too flattering.
    const ps = [
      period({ account: "checking", from: "2026-08-01", to: "2026-08-31" }),
      period({ account: "card", from: "2026-07-01", to: "2026-07-31" }),
    ];
    expect(coverageThrough(ps)).toBe("2026-07-31");
  });

  it("is undefined with nothing to go on", () => {
    expect(coverageThrough([])).toBeUndefined();
  });

  it("clips a ledger's usable transactions at that date", () => {
    const rows = [
      tx("2026-07-10", "CARD SPEND", -50, "card"),
      tx("2026-08-10", "CHECKING SPEND", -60, "checking"),
    ];
    const l = unverifiedLedger(rows, "2026-07-31", "no opening balance on the card export");
    expect(covered(l).map((t) => t.description)).toEqual(["CARD SPEND"]);
    expect(l.txns).toHaveLength(2);
  });
});

describe("reconcile — transactions belonging to no statement", () => {
  it("reports them rather than dropping them, and refuses the ledger", () => {
    const rows = [tx("2026-06-03", "IN PERIOD", 0), tx("2026-05-03", "BEFORE ANY STATEMENT", -40)];
    const r = reconcile(rows, [period()]);
    expect(r.uncovered.map((t) => t.description)).toEqual(["BEFORE ANY STATEMENT"]);
    expect(r.ok).toBe(false);
    expect(r.periods[0].counted).toBe(1);
  });

  it("does not let another account's transactions balance this one", () => {
    const rows = [tx("2026-06-03", "CARD SPEND", -100, "card")];
    const r = reconcile(rows, [period({ closing: usd(900) })]);
    expect(r.periods[0].counted).toBe(0);
    expect(r.periods[0].discrepancy.minor).toBe(usd(-100).minor);
    expect(r.uncovered).toHaveLength(1);
  });
});

describe("reconcile — a currency that is not the statement's", () => {
  it("refuses to convert, and says converting is a decision", () => {
    const rows: Txn[] = [
      { date: "2026-06-03", description: "PARIS HOTEL", amount: fromMajor(-200, "EUR"), account: "checking" },
    ];
    const r = reconcile(rows, [period()]);
    expect(r.ok).toBe(false);
    const c = r.problems.find((p) => p.kind === "currency")!;
    expect(c.detail).toContain("EUR");
    expect(c.detail).toContain("decision");
    // It is excluded from the arithmetic rather than added as if it were dollars.
    expect(r.periods[0].computed.minor).toBe(usd(1000).minor);
  });
});

describe("the unverified escape hatch", () => {
  it("demands a reason", () => {
    expect(() => unverifiedLedger([], "2026-06-30", "  ")).toThrow(/why/);
  });

  it("marks itself, so a figure standing on unchecked data can say so", () => {
    const l = unverifiedLedger([tx("2026-06-03", "X", -10)], "2026-06-30", "Chase export has no opening balance");
    expect(l.unverified).toBe(true);
    expect(provenance(l)).toMatch(/^UNVERIFIED/);
    expect(provenance(l)).toContain("Chase export has no opening balance");
  });

  it("a reconciled ledger's provenance says so instead", () => {
    const r = reconcile([tx("2026-06-03", "X", 0)], [period()]);
    expect(provenance(r.ledger!)).toMatch(/^reconciled/);
    expect(provenance(r.ledger!)).toContain("covered through 2026-06-30");
  });
});

describe("the ledger is a TYPE, not a convention", () => {
  it("only reconcile and unverifiedLedger can produce one", () => {
    // The brand is a unique symbol with no exported value, so this is the whole surface. If a
    // capability downstream takes a ReconciledLedger, an unchecked array cannot reach it — and that
    // is the point: every figure here is arithmetic over a list, and arithmetic over an incomplete
    // list produces a plausible number rather than an error.
    const fromReconcile: ReconciledLedger | undefined = reconcile([], [period()]).ledger;
    const fromHatch: ReconciledLedger = unverifiedLedger([], "2026-06-30", "no statement available");
    expect(fromReconcile).toBeDefined();
    expect(fromHatch.unverified).toBe(true);
    // @ts-expect-error a raw array is not a ledger, and the compiler is what enforces it
    const bogus: ReconciledLedger = [tx("2026-06-03", "X", -10)];
    expect(Array.isArray(bogus)).toBe(true);
  });

  it("no periods at all is not a pass", () => {
    const r = reconcile([], []);
    expect(r.ok).toBe(false);
    expect(r.ledger).toBeUndefined();
  });
});
